mapper.select:
select CTP.CUSTOM_TIME_PERIOD_CODE as CTP_CUSTOM_TIME_PERIOD_CODE, CTP.CUSTOM_TIME_PERIOD_CODE_LANG as CTP_CUSTOM_TIME_PERIOD_CODE_LANG, ATE.AMOUNT as ATE_AMOUNT, GFT.DESCRIPTION as GFT_DESCRIPTION, GFT.DESCRIPTION_LANG as GFT_DESCRIPTION_LANG from GL_ACCOUNT GA inner join ACCTG_TRANS_ENTRY ATE on ATE.GL_ACCOUNT_ID = GA.GL_ACCOUNT_ID inner join GL_FISCAL_TYPE GFT on GFT.GL_FISCAL_TYPE_ID = ATE.GL_FISCAL_TYPE_ID inner join ACCTG_TRANS AT on AT.ACCTG_TRANS_ID = ATE.ACCTG_TRANS_ID and AT.WORK_EFFORT_REVISION_ID is null inner join CUSTOM_TIME_PERIOD CTP on CTP.PERIOD_TYPE_ID = GA.PERIOD_TYPE_ID and CTP.THRU_DATE = AT.TRANSACTION_DATE where GA.GL_ACCOUNT_ID = #{glAccountId}
and AT.ROLE_TYPE_ID = #{orgUnitRoleTypeId} and AT.PARTY_ID = #{orgUnitId}
and ATE.VOUCHER_REF = #{workEffortMeasureId}
order by CTP.FROM_DATE asc

select wea.*, wet.work_effort_type_id as WET_work_effort_type_id, wet.description as WET_description, wet.description_lang as WET_description_lang, wet2.work_effort_type_id as WET2_work_effort_type_id, wet2.description as WET2_description, wet2.description_lang as WET2_description_lang
from work_effort_analysis wea join work_effort_type wet on wet.work_effort_type_id = wea.work_effort_type_id join work_effort_type wet2 on wet2.work_effort_type_id = wet.parent_type_id
where wet.parent_type_id = #{context,jdbcType=VARCHAR}
